function threefoldBreachValid(s){return !s.finished&&s.owner===p&&s.world===dungeon&&!dead&&p?.hp>0&&s.time<6&&s.target?.hp>0&&!s.target.dummy&&enemies.includes(s.target)&&dist(p,s.target)<=500&&lineClear(p,s.target);}
function threefoldBreachSector(s){const a=Math.atan2(p.y-s.target.y,p.x-s.target.x)-s.basis+Math.PI/4;return Math.floor(((a%(2*Math.PI))+2*Math.PI)%(2*Math.PI)/(Math.PI/2));}
const threefoldBreachCastBase=castCraftedSkill;
castCraftedSkill=(build,...args)=>{const result=threefoldBreachCastBase(build,...args);if(GEM[build.type]?.signature!==119)return result;const s=signatureSpells.at(-1);if(s?.mode!==119)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==119||v===s);Object.assign(s,{owner:p,world:dungeon,finished:false,sectors:new Set()});if(!threefoldBreachValid(s)){s.finished=true;signatureSpells=signatureSpells.filter(v=>v!==s);say('500以内の敵を狙ってください');}else s.basis=Math.atan2(p.y-s.target.y,p.x-s.target.x);return result;};
let threefoldBreachResolving=false;
const threefoldBreachHitBase=hit;
hit=(e,d)=>{const s=signatureSpells.find(v=>v.mode===119&&v.target===e&&threefoldBreachValid(v)),before=e?.hp,eligible=s&&started&&!paused&&!threefoldBreachResolving&&cadenceNormalAction&&classHitKind==='normal'&&!classNormalHit&&!treeExplosion&&!e.dotTick&&dist(p,e)<=180,sector=eligible?threefoldBreachSector(s):-1;
 const result=threefoldBreachHitBase(e,d);
 if(eligible&&threefoldBreachValid(s)&&e.hp<before&&!s.sectors.has(sector)){s.sectors.add(sector);if(s.sectors.size===3){s.finished=true;e.reactionVuln=Math.max(e.reactionVuln||0,30);e.reactionVulnTime=Math.max(e.reactionVulnTime||0,4);const kind=classHitKind;threefoldBreachResolving=true;classHitKind='skill';try{spellHit(e,s.damage*1.5,s.build);burst(e.x,e.y,65,ELEMENTS[s.build.elements[0]].color);playSignatureAudio(119,true,e.x,e.y);}finally{classHitKind=kind;threefoldBreachResolving=false;}}}return result;};
const threefoldBreachStepBase=stepSignature;
stepSignature=(s,dt)=>{if(s.mode!==119)return threefoldBreachStepBase(s,dt);if(!threefoldBreachValid(s)){s.finished=true;return false;}if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time+=dt;if(s.time>=6-1e-8){s.finished=true;return false;}return true;};
